settingspath=P/'production-settings.json';settings=json.loads(settingspath.read_text());settings.update({'resolve_timeline':'Eleanor-EuropeanTravel-Tight','presenter_layout':manifest['presenter_layout'],'timeline_frames':2120,'timeline_seconds':2120/30,'quiet_gap_cut_map':str((R/'cut-map.json').relative_to(root)),'resolve_audio':'Selected exact MP3 decoded to PCM; 27 quiet gaps removed with matching presenter cuts, no additional speed change'});settingspath.write_text(json.dumps(settings,indent=2)+'\n')
