review=st.add_review(r['id'],'automated',{'scope':'finished-media-technical','verdict':'PASS','artifact_path':str(movie.relative_to(root)),'artifact_sha256':sha,'receipt_path':str((Q/'delivery-verification.json').relative_to(root)),'notes':'Agent technical review, not human approval. Raw machine layout flags reconciled against actual native frames; audio checks and exact narration pass.'},rev)
